class TestChatReadStateInvariants:
    def test_read_state_monotonicity(self) -> None:
        # Read-state only moves forward (ADR 0006)
        # Tab 1: advances to 45
        s1 = clamp_read_state(current_last_read_seq=0, through_seq=45, latest_seq=50)
        assert s1 == 45
        # Tab 2: stale update with 40 -> remains 45
        s2 = clamp_read_state(current_last_read_seq=45, through_seq=40, latest_seq=50)
        assert s2 == 45

    def test_read_ahead_forbidden(self) -> None:
        # through_seq > latest_seq is 422 READ_AHEAD
        with pytest.raises(ReadAheadError):
            clamp_read_state(current_last_read_seq=10, through_seq=55, latest_seq=50)


class TestChatContentValidation:
    def test_valid_text_message(self) -> None:
        validate_text_content("Chào bạn, mai họp nhé!")
        validate_text_content("A" * MAX_TEXT_CODEPOINTS)

    def test_invalid_text_message(self) -> None:
        with pytest.raises(DomainError):
            validate_text_content("")
        with pytest.raises(DomainError):
            validate_text_content("A" * (MAX_TEXT_CODEPOINTS + 1))

    def test_attachment_size_limits(self) -> None:
        # Empty file/audio raises
        with pytest.raises(InvalidAttachmentError):
            validate_attachment(kind="file", byte_size=0)

        # File within 25 MiB passes
        validate_attachment(kind="file", byte_size=MAX_FILE_BYTES)
        with pytest.raises(UploadTooLargeError):
            validate_attachment(kind="file", byte_size=MAX_FILE_BYTES + 1)

        # Audio within 10 MiB and 300s passes
        validate_attachment(kind="audio", byte_size=MAX_AUDIO_BYTES, duration_ms=300_000)
        with pytest.raises(UploadTooLargeError):
            validate_attachment(kind="audio", byte_size=MAX_AUDIO_BYTES + 1, duration_ms=10_000)
        with pytest.raises(InvalidAttachmentError):
            validate_attachment(kind="audio", byte_size=1000, duration_ms=300_001)


class TestChatUnreadSummaryFiltering:
    def test_summary_filtering_and_omitted_count(self) -> None:
        conv_id = uuid.uuid4()
        reader_id = uuid.uuid4()
        friend_id = uuid.uuid4()
        now = datetime.now(UTC)

        # Create 104 messages from friend (seq 1 to 104) plus 10 messages from reader and 5 audio
        messages: list[SummaryCandidateMessage] = []
        for i in range(1, 105):
            messages.append(
                SummaryCandidateMessage(
                    id=uuid.uuid4(),
                    conversation_id=conv_id,
                    seq=i,
                    sender_id=friend_id,
                    content_type="text",
                    text=f"Tin nhan so {i}",
                    created_at=now,
                )
            )

        # Reader's own message
        messages.append(
            SummaryCandidateMessage(
                id=uuid.uuid4(),
                conversation_id=conv_id,
                seq=105,
                sender_id=reader_id,
                content_type="text",
                text="Tin nhan cua chinh minh",
                created_at=now,
            )
        )

        # Audio message from friend
        messages.append(
            SummaryCandidateMessage(
                id=uuid.uuid4(),
                conversation_id=conv_id,
                seq=106,
                sender_id=friend_id,
                content_type="audio",
                text=None,
                created_at=now,
            )
        )

        # 104 eligible text messages from friend:
        # Should return exactly the newest 100 messages (seq 5 to 104) and omitted_count = 4
        selected, omitted = filter_messages_for_summary(
            messages, reader_id=reader_id, max_count=100
        )
        assert len(selected) == 100
        assert omitted == 4
        assert selected[0].seq == 5
        assert selected[-1].seq == 104
        # Verify all selected are strictly text from friend
        for msg in selected:
            assert msg.sender_id == friend_id
            assert msg.content_type == "text"
